<?php
namespace Tests\Unit\Scheduling;
use App\Modules\Scheduling\Models\{Appointment,EventType}; use App\Modules\Scheduling\Services\IcsGenerator; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class IcsGeneratorTest extends TestCase {use RefreshDatabase; public function test_it_escapes_untrusted_ics_content():void{$type=EventType::create(['name'=>"Reunião\nINJECT",'slug'=>'reuniao','duration_minutes'=>30,'slot_interval_minutes'=>15,'location_type'=>'custom','location_value'=>"Sala, 1\r\nATTENDEE:bad",'buffer_before_minutes'=>0,'buffer_after_minutes'=>0,'minimum_notice_minutes'=>0,'maximum_days_ahead'=>30,'active'=>true]);$a=Appointment::create(['event_type_id'=>$type->id,'scheduled_start_at'=>'2026-09-01 12:00:00','scheduled_end_at'=>'2026-09-01 12:30:00','timezone'=>'UTC','status'=>'confirmed','guest_name'=>'Teste','guest_email'=>'test@example.test','cancellation_token_hash'=>str_repeat('a',64),'reschedule_token_hash'=>str_repeat('b',64)]);$ics=app(IcsGenerator::class)->generate($a);$this->assertStringContainsString('SUMMARY:Reunião\\nINJECT',$ics);$this->assertStringNotContainsString("\r\nATTENDEE:bad",$ics);}}
